VALUES (38, 'tt0338013', NULL, 'Eternal Sunshine of the Spotless Mind', 'Eternal Sunshine of the Spotless Mind', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg', 'https://image.tmdb.org/t/p/original/W1ffLQGHoxfAOq0ZYdPtJlvAdb.jpg', 'Joel Barish, heartbroken that his girlfriend underwent a procedure to erase him from her memory, decides to do the same. However, as he watches his memories of her fade away, he realises that he still loves her, and may be too late to correct his mistake.', NULL, NULL, 17.4595, 8.089, 0, 1.50862448979591846e+02, '2026-07-15 12:01:52', '2026-10-17 22:32:03')
