VALUES (80, 'tt0381681', NULL, 'Before Sunset', 'Before Sunset', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/4sW5XH9ZfYXpvFzev00S1IGAEbg.jpg', 'https://image.tmdb.org/t/p/original/tcZi0LQc5iu2u6i5aOWyj9NBBvl.jpg', 'Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.', NULL, NULL, 5.7426, 7.8, 0, 2.31680000000000028e+01, '2026-07-15 12:01:52', '2026-10-17 22:32:03')
