VALUES (297, 'tt0119643', NULL, 'Meet Joe Black', 'Meet Joe Black', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/fDPAjvfPMomkKF7cMRmL5Anak61.jpg', 'https://image.tmdb.org/t/p/original/uMBByiSDpgFwWVegAtwwnuzvogJ.jpg', 'Bill Parrish has it all - success, wealth and power. Days before his 65th birthday, he receives a visit from a mysterious stranger, Joe Black, who soon reveals himself as Death. In exchange for extra time, Bill agrees to serve as Joe''s earthly guide. But will he regret his choice when Joe unexpectedly falls in love with Bill''s beautiful daughter Susan?', NULL, NULL, 13.6399, 7.37, 0, 1.79741666666666652e+01, '2026-07-15 12:01:52', '2026-10-17 22:32:03')
