VALUES (6878, 'tt0107131', NULL, 'Homeward Bound: The Incredible Journey', 'Homeward Bound: The Incredible Journey', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/el6dJEpK97OJRQiQhuiSGk2jkV5.jpg', 'https://image.tmdb.org/t/p/original/xDwDhLtQnA7jK4f7DVkdeSvZnAp.jpg', 'Before the Seavers leave for a family vacation to San Francisco, they drop off their pets -- Chance, an adventurous American bulldog; Shadow, a wise golden retriever; and Sassy, a cautious cat -- at a friend''s ranch. But when the animals start to worry that they''ve been left for good, the three embark together on a treacherous and thrilling journey to find their way back home through the California wilderness.', NULL, NULL, 6.764, 6.993, 0, 2.6452727272727273e+01, '2026-07-20 01:02:04', '2026-10-17 22:32:03')
