VALUES (39467, 'tt0120211', NULL, 'Still Breathing', 'Still Breathing', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/xzddUnxNOs1DTyygqojRRYkPG6C.jpg', 'https://image.tmdb.org/t/p/original/fe1MtZSdbJ6iper1QjpjHOujvRp.jpg', 'Two lost souls: she a con-artist in L.A.; he a puppeteer in San Antonio have the same dream linking each with the other. He travels to L.A. to find this woman he has become obsessed with. She resists, afraid of his kooky ideas until she travels with him to San Antonio and meets his wise grandmother. Story of two disparate people linked by "fate" gets increasingly interesting as it rolls along.', NULL, NULL, 2.5645, 6.5, 0, 1.00266666666666655e+01, '2026-08-03 14:31:56', '2026-10-17 22:32:03')
