VALUES (287424, 'tt1881002', NULL, 'Maggie', 'Maggie', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/twa9gXjocLM629sJrQYVtmF306R.jpg', 'https://image.tmdb.org/t/p/original/8LYxSH8ZJzKbS3kNIELsVc05RNH.jpg', 'There''s a deadly zombie epidemic threatening humanity, but Wade, a small-town farmer and family man, refuses to accept defeat even when his daughter Maggie becomes infected. As Maggie''s condition worsens and the authorities seek to eradicate those with the virus, Wade is pushed to the limits in an effort to protect her. Joely Richardson co-stars in this post-apocalyptic thriller.', NULL, NULL, 5.1937, 5.403, 0, 2.01, '2026-08-11 22:09:33', '2026-10-17 22:32:03')
