VALUES (10731, 'tt0109446', NULL, 'The Client', 'The Client', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/oLdkJ4ZjxPtFSUChdjDQvHM9l75.jpg', 'https://image.tmdb.org/t/p/original/ncU6X4hosU9srxqC0hGxajZvAyD.jpg', 'A street-wise kid, Mark Sway, sees the suicide of Jerome Clifford, a prominent Louisiana lawyer, whose current client is Barry ''The Blade'' Muldano, a Mafia hit-man. Before Jerome shoots himself, he tells Mark where the body of a Senator is buried. Clifford shoots himself and Mark is found at the scene, and both the FBI and the Mafia quickly realize that Mark probably knows more than he says.', NULL, NULL, 8.1987, 6.7, 0, 9.03, '2026-08-19 01:49:52', '2026-10-17 22:32:03')
