VALUES (1132704, 'tt2050645', NULL, 'The Mirror Mask', 'The Mirror Mask', 'movie', NULL, NULL, NULL, 'The Mirror Mask was created as a commission for the 2005 Contour Biennial of Video Art and was originally exhibited in a multi-channel format with drawings. The feature-length edit was made simultaneously. Working from the Biennial’s theme of feminine power, the video’s exploration uses symbols from both Flemish and Egyptian art reinterpreted through CGI, latex sculptures and low-tech animation programs – the images of the past translated onto a frozen computerized canvas.', NULL, NULL, 0.4288, 0.0, 0, 8.11, '2026-08-20 01:43:50', '2026-10-17 22:32:03')
